/**
 * Slack continuation fixtures for DM messages, reactions, and Block Kit
 * clicks, shared by the two continuation
 * vocabulary copies: `internal/continuation-identity.ts` (July) and the
 * control plane's `agentSdkConversationIdentity.ts` (server-shared). The
 * hosted control plane stamps the lane from these payloads and the guest
 * derives the same key from its parsers, so a shape only one copy
 * understands fails CI on the other side.
 *
 * Pure data: no imports, so the server-shared suite can load it by relative
 * path without pulling `@grok/agent-sdk` into the control plane.
 */
function reactionAddedBody(item) {
    return {
        type: "event_callback",
        team_id: "T0FIXTURE",
        api_app_id: "A0FIXTURE",
        event_id: "Ev0REACTION",
        authorizations: [{ team_id: "T0FIXTURE", user_id: "U0BOT", is_bot: true }],
        event: {
            type: "reaction_added",
            user: "U0REACTOR",
            reaction: "white_check_mark",
            item_user: "U0AUTHOR",
            item,
            event_ts: "1719000100.000300",
        },
    };
}
function agentSessionStoppedBody(channel) {
    return {
        type: "event_callback",
        team_id: "T0FIXTURE",
        api_app_id: "A0FIXTURE",
        event_id: "Ev0STOP",
        authorizations: [{ team_id: "T0FIXTURE", user_id: "U0BOT", is_bot: true }],
        event: {
            type: "agent_session_stopped",
            user: "U0STOPPER",
            channel,
            thread_ts: "1719000000.000200",
            event_ts: "1719000400.000600",
        },
    };
}
function blockActionsPayload(args) {
    return {
        type: "block_actions",
        api_app_id: "A0FIXTURE",
        trigger_id: "1111.2222.fixturetrigger",
        team: { id: "T0FIXTURE", domain: "fixture" },
        user: { id: "U0CLICKER", username: "clicker", team_id: "T0FIXTURE" },
        container: args.container,
        channel: args.channelId === undefined ? undefined : { id: args.channelId, name: "fixture-channel" },
        message: args.message,
        actions: [
            {
                type: "button",
                action_id: "deploy_confirm",
                block_id: "deploy_row",
                text: { type: "plain_text", text: "Deploy" },
                value: "deploy",
                action_ts: "1719000300.000500",
            },
        ],
    };
}
function dmMessageBody(event) {
    return {
        type: "event_callback",
        team_id: "T0FIXTURE",
        api_app_id: "A0FIXTURE",
        event_id: "Ev0MESSAGE",
        event: {
            type: "message",
            channel: "D0FIXTURE",
            channel_type: "im",
            user: "U0AUTHOR",
            ...event,
        },
    };
}
export const SLACK_CONTINUATION_FIXTURES = [
    {
        name: "a top-level DM roots its own thread",
        eventType: "message",
        payload: dmMessageBody({ text: "hello", ts: "1719000000.000100" }),
        expectedKey: "cont:D0FIXTURE",
        dmThreadKey: "cont:D0FIXTURE:1719000000.000100",
    },
    {
        name: "a reply in a DM thread joins the root",
        eventType: "message",
        payload: dmMessageBody({
            text: "more",
            ts: "1719000000.000200",
            thread_ts: "1719000000.000100",
        }),
        expectedKey: "cont:D0FIXTURE",
        dmThreadKey: "cont:D0FIXTURE:1719000000.000100",
    },
    {
        name: "a later top-level DM roots a new thread",
        eventType: "message",
        payload: dmMessageBody({ text: "new topic", ts: "1719000000.000300" }),
        expectedKey: "cont:D0FIXTURE",
        dmThreadKey: "cont:D0FIXTURE:1719000000.000300",
    },
    {
        name: "a reaction roots the lane at the reacted-to message",
        eventType: "reaction_added",
        payload: reactionAddedBody({
            type: "message",
            channel: "C0FIXTURE",
            ts: "1719000000.000200",
        }),
        expectedKey: "cont:C0FIXTURE:1719000000.000200",
    },
    {
        name: "a reaction in a DM keys the IM",
        eventType: "reaction_added",
        payload: reactionAddedBody({
            type: "message",
            channel: "D0FIXTURE",
            ts: "1719000000.000200",
        }),
        expectedKey: "cont:D0FIXTURE",
        dmThreadKey: "cont:D0FIXTURE:1719000000.000200",
    },
    {
        name: "a reaction on a file binds no thread",
        eventType: "reaction_added",
        payload: reactionAddedBody({ type: "file", file: "F0FIXTURE" }),
        expectedKey: undefined,
    },
    {
        name: "a Stop click continues the thread it was clicked in",
        eventType: "agent_session_stopped",
        payload: agentSessionStoppedBody("C0FIXTURE"),
        expectedKey: "cont:C0FIXTURE:1719000000.000200",
    },
    {
        name: "a Stop click in a DM keys the IM",
        eventType: "agent_session_stopped",
        payload: agentSessionStoppedBody("D0FIXTURE"),
        expectedKey: "cont:D0FIXTURE",
        dmThreadKey: "cont:D0FIXTURE:1719000000.000200",
    },
    {
        name: "a click on a threaded reply continues the parent thread",
        eventType: "block_actions",
        payload: blockActionsPayload({
            channelId: "C0FIXTURE",
            message: {
                type: "message",
                user: "U0BOT",
                ts: "1719000200.000400",
                thread_ts: "1719000000.000200",
                text: "Deploy?",
            },
            container: {
                type: "message",
                channel_id: "C0FIXTURE",
                message_ts: "1719000200.000400",
                thread_ts: "1719000000.000200",
            },
        }),
        expectedKey: "cont:C0FIXTURE:1719000000.000200",
    },
    {
        name: "a click on a top-level post roots the lane at that post",
        eventType: "block_actions",
        payload: blockActionsPayload({
            channelId: "C0FIXTURE",
            message: { type: "message", user: "U0BOT", ts: "1719000200.000400", text: "Deploy?" },
            container: {
                type: "message",
                channel_id: "C0FIXTURE",
                message_ts: "1719000200.000400",
            },
        }),
        expectedKey: "cont:C0FIXTURE:1719000200.000400",
    },
    {
        name: "a click in a DM keys the IM",
        eventType: "block_actions",
        payload: blockActionsPayload({
            channelId: "D0FIXTURE",
            message: { type: "message", user: "U0BOT", ts: "1719000200.000400", text: "Deploy?" },
            container: {
                type: "message",
                channel_id: "D0FIXTURE",
                message_ts: "1719000200.000400",
            },
        }),
        expectedKey: "cont:D0FIXTURE",
        dmThreadKey: "cont:D0FIXTURE:1719000200.000400",
    },
    {
        name: "a click inside a modal binds no thread",
        eventType: "block_actions",
        payload: blockActionsPayload({
            container: { type: "view", view_id: "V0FIXTURE" },
        }),
        expectedKey: undefined,
    },
];
